package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.ConflictException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.web.bind.annotation.PathVariable;

/** Save an edited person; refused (409) when someone else has saved them since the editor loaded its version. */
public class SavePerson {
    public void save(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            @Val PersonRequest request, ServerHttpConnection connection, PersonRepository repository,
            Audit audit, Rollup rollup, Out<Person> person) throws BadRequestException, ConflictException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long pid;
        try {
            pid = Long.parseLong(personId == null ? "" : personId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such person");
        }
        if (request.version() == null) {
            throw new BadRequestException("version is required");
        }
        if (!repository.exists(id, pid)) {
            throw new BadRequestException("no such person");
        }
        if (repository.nameTaken(id, request.name(), pid)) {
            throw new BadRequestException("name is already in use");
        }
        long version = request.version();
        Rollup.Snapshot before = rollup.take(id);
        boolean updated;
        try {
            updated = repository.update(id, pid, version, request.name(), request.grade());
        } catch (DuplicateKeyException e) {
            throw new BadRequestException("name is already in use");
        }
        if (!updated) {
            throw new ConflictException("someone else has saved this person; showing their current values");
        }
        Person saved = repository.find(id, pid);
        audit.record("PERSON_EDITED sheet=" + id + " by=" + by + " name=" + saved.name()
                + " grade=" + saved.grade());
        rollup.record(id, by, before);
        person.set(saved);
    }
}
package net.officefloor.hq.app.person;

import java.util.Set;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the person form: a name is required (trimmed; unique on the sheet, checked when saved), the grade must be A, B or C. */
public class ValidatePerson {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> person) throws BadRequestException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
        if (name.isEmpty()) {
            throw new BadRequestException("name is required");
        }
        if (!GRADES.contains(grade)) {
            throw new BadRequestException("grade must be A, B or C");
        }
        person.set(new PersonRequest(name, grade, request.version()));
    }
}
# The sheet's people in the order they were added, re-read from the store.
load:
  class: net.officefloor.hq.app.person.LoadPeople
  govern: [ readonly-transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPeople
# Add a person to the sheet: a name (required) and a grade (A, B or C).
validate:
  class: net.officefloor.hq.app.person.ValidatePerson
  next: save
save:
  class: net.officefloor.hq.app.person.AddPerson
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
# Edit a person on the sheet: their name (required) and grade (A, B or C).
validate:
  class: net.officefloor.hq.app.person.ValidatePerson
  next: save
save:
  class: net.officefloor.hq.app.person.SavePerson
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
-- People on a sheet, listed in the order they were added (by id). A grade is one of A, B or C.
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(500) NOT NULL,
    grade    VARCHAR(1)   NOT NULL
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- The version of a person's stored values: starts at 1 and goes up by one each time they are
-- saved, so an editor that loaded an older version is refused rather than overwriting a newer save.
ALTER TABLE person ADD COLUMN version BIGINT NOT NULL DEFAULT 1;
-- A person's statements: how many have been taken, and the last one's due-total (as shown, so
-- possibly 'n/a') and date (the sheet's today when it was taken). Null until the first statement.
ALTER TABLE person ADD COLUMN statement_count BIGINT DEFAULT 0 NOT NULL;
ALTER TABLE person ADD COLUMN stated_total VARCHAR(20);
ALTER TABLE person ADD COLUMN statement_date DATE;
-- A claim bound by its person's last statement: it shows and totals stated_due (the figure it had
-- then; null when it had none, its due then staying live) until the next statement rebinds or
-- unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(19, 2);

