  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
# Take a person's statement: record their due-total, and bind each of their counting claims to the
# figure it has now (unbinding the rest), until their next statement.
take:
  class: net.officefloor.hq.app.statement.TakeStatement
  govern: [ transaction ]
