package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.period.PeriodGuard;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class AddClaim {
    public void add(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            @Val ClaimInput input, ServerHttpConnection connection, ClaimRepository repository,
            SheetRepository sheets, PeriodRepository periods, Audit audit, Rollup rollup, Out<Claim> claim) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long pid;
        try {
            pid = Long.parseLong(personId == null ? "" : personId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such person");
        }
        if (!repository.personExists(id, pid)) {
            throw new BadRequestException("no such person");
        }
        LocalDate date = input.date() != null ? input.date() : sheets.today(id);
        PeriodGuard.open(periods, id, date);
        Rollup.Snapshot before = rollup.take(id);
        Claim added = repository.add(id, pid, input.amount(), date, input.note());
        audit.record("CLAIM_ADDED sheet=" + id + " by=" + by + " person=" + repository.personName(id, pid)
                + " amount=" + added.amount() + " date=" + added.date());
        rollup.record(id, by, before);
        claim.set(added);
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the claim form: an amount is required (a number with up to two decimals, 0.00 or more), a
 *  blank date takes the sheet's today, the note may be empty. */
public class ValidateClaim {
    public void validate(@RequestBody ClaimRequest request, Out<ClaimInput> claim) throws BadRequestException {
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        String date = request == null || request.date() == null ? "" : request.date().trim();
        String note = request == null || request.note() == null ? "" : request.note().trim();
        LocalDate on = null;
        if (!date.isEmpty()) {
            try {
                on = LocalDate.parse(date);
            } catch (DateTimeParseException e) {
                throw new BadRequestException("date must be yyyy-mm-dd");
            }
        }
        claim.set(new ClaimInput(ClaimInput.amount(amount), on, note));
    }
}
package net.officefloor.hq.app.quick;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.period.PeriodGuard;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.web.bind.annotation.PathVariable;

/** Add a draft claim, dated the sheet's today with an empty note, for the person with this name (ignoring
 *  case), adding them first with grade A when the sheet has no one by that name. One change: every check
 *  runs before anything is written, so a refusal leaves no new person and no audit record behind. */
public class QuickAdd {
    public void add(@PathVariable("sheetId") String sheetId, @Val QuickAddInput input,
            ServerHttpConnection connection, PersonRepository people, ClaimRepository claims, SheetRepository sheets,
            PeriodRepository periods, Audit audit, Rollup rollup, Out<Claim> claim) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!people.sheetExists(id)) {
            throw new BadRequestException("no such sheet");
        }
        LocalDate date = sheets.today(id);
        PeriodGuard.open(periods, id, date);
        Person person = people.findByName(id, input.name());
        if (person == null) {
            Rollup.Snapshot before = rollup.take(id);
            try {
                person = people.add(id, input.name(), "A");
            } catch (DuplicateKeyException e) {
                throw new BadRequestException("name is already in use");
            }
            audit.record("PERSON_ADDED sheet=" + id + " by=" + by + " name=" + person.name()
                    + " grade=" + person.grade());
            rollup.record(id, by, before);
        }
        Rollup.Snapshot before = rollup.take(id);
        Claim added = claims.add(id, person.id(), input.amount(), date, "");
        audit.record("CLAIM_ADDED sheet=" + id + " by=" + by + " person=" + person.name()
                + " amount=" + added.amount() + " date=" + added.date());
        rollup.record(id, by, before);
        claim.set(added);
    }
}
package net.officefloor.hq.app.sheet;

import java.sql.Date;
import java.time.LocalDate;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class SheetRepository {

    private final JdbcTemplate jdbc;

    public SheetRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet with this id, made empty (its today the real date) when the id was never used. */
    public Sheet loadOrCreate(String id, String user) {
        Integer known = jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, id);
        if (known == null || known == 0) {
            try {
                jdbc.update("INSERT INTO sheet (id, created_by, today) VALUES (?, ?, ?)", id, user,
                        Date.valueOf(LocalDate.now()));
            } catch (DuplicateKeyException made) {
                // another user loaded the same new id at the same moment: it is made either way
            }
        }
        return new Sheet(id, today(id).toString());
    }

    /** The sheet's today: the date every date decision and default in the sheet uses. */
    public LocalDate today(String id) {
        Date today = jdbc.queryForObject("SELECT today FROM sheet WHERE id = ?", Date.class, id);
        return today.toLocalDate();
    }

    /** Set the sheet's today; false when there is no such sheet. */
    public boolean setToday(String id, LocalDate today) {
        return jdbc.update("UPDATE sheet SET today = ? WHERE id = ?", Date.valueOf(today), id) > 0;
    }
}

