import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { claimsKey } from '../claims/useClaims';
import { peopleKey, usePeople, type Person } from '../people/usePeople';

/** A person's statements: how many have been taken, the last one's due-total and date (blank before
 *  the first), and a button that takes one. Taking a statement records their due-total and binds each
 *  of their counting claims to the figure it has then (unbinding the rest), until the next one. */
function PersonStatement({ sheetId, personId }: { sheetId: string; personId: number }) {
  const people = usePeople(sheetId);
  const queryClient = useQueryClient();
  const p = people.data?.find((x) => x.id === personId);

  const take = useMutation({
    mutationFn: () =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/statement`, {}),
    onSuccess: async () => {
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
      ]);
    },
  });

  return (
    <>
      <td data-testid="person-statement-count">{p?.statementCount ?? 0}</td>
      <td data-testid="person-stated-total">{p?.statedTotal ?? ''}</td>
      <td data-testid="person-statement-date">{p?.statementDate ?? ''}</td>
      <td>
        <button
          type="button"
          data-testid="person-statement"
          disabled={take.isPending}
          onClick={() => {
            take.reset();
            take.mutate();
          }}
        >
          Statement
        </button>
        {take.isError && <span data-testid="person-error">{take.error.message}</span>}
      </td>
    </>
  );
}

export const contributions = [
  PersonColumnHead.fill({
    order: 30,
    Component: () => (
      <>
        <th>Statements</th>
        <th>Stated total</th>
        <th>Stated on</th>
        <th />
      </>
    ),
  }),
  PersonCells.fill({ order: 30, Component: PersonStatement }),
];
import { createFileRoute } from '@tanstack/react-router';
import { CurrentUser, SignIn } from '../features/session/SignIn';
import { useActiveSheet, useSignedInUser } from '../features/session/useSession';
import { SheetPicker } from '../features/sheet/SheetPicker';
import { SheetBody } from '../slots/defs/sheetBody';

// The one screen. Sign in first; then choose a sheet; the sheet's own features fill SheetBody.
export const Route = createFileRoute('/')({
  component: Home,
});

function Home() {
  const [user] = useSignedInUser();
  const [sheetId] = useActiveSheet();
  if (!user) return <SignIn />;
  return (
    <>
      <CurrentUser />
      <SheetPicker />
      {sheetId && (
        <section data-testid="sheet-body" key={sheetId}>
          <SheetBody.Slot sheetId={sheetId} user={user} />
        </section>
      )}
    </>
  );
}
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { useState } from 'react';
import { type QueryClient, useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useActiveSheet } from '../session/useSession';

type Sheet = { id: string };

/** Resolve once the screen has read the sheet: its queries have mounted (after the next frame) and
 *  none of them is still fetching. */
function sheetRead(queryClient: QueryClient, id: string): Promise<void> {
  const fetching = () => queryClient.isFetching({ queryKey: ['sheet', id] }) > 0;
  return new Promise((resolve) => {
    requestAnimationFrame(() =>
      setTimeout(() => {
        if (!fetching()) return resolve();
        const stop = queryClient.getQueryCache().subscribe(() => {
          if (!fetching()) {
            stop();
            resolve();
          }
        });
      }, 0),
    );
  });
}

/** Choose a sheet by typing its id and loading it. Loading (even the same id again) drops every
 *  ['sheet', id, ...] query, so the sheet is re-read from the store. The active id is shown once
 *  the screen has read the sheet, so a shown id means its rows are on screen. */
export function SheetPicker() {
  const [active, setActive] = useActiveSheet();
  const [id, setId] = useState(active);
  const [shown, setShown] = useState(active);
  const queryClient = useQueryClient();
  const load = useMutation({
    mutationFn: async (raw: string) => {
      const want = raw.trim();
      if (want === '') throw new Error('sheet id is required');
      return postJson<Sheet>(`/api/sheets/${encodeURIComponent(want)}`, {});
    },
    onSuccess: async (sheet) => {
      queryClient.removeQueries({ queryKey: ['sheet', sheet.id] });
      setShown('');
      setActive(sheet.id);
      await sheetRead(queryClient, sheet.id);
      setShown(sheet.id);
    },
  });

  return (
    <form
      data-testid="sheet-form"
      onSubmit={(e) => {
        e.preventDefault();
        load.reset();
        load.mutate(id);
      }}
    >
      <label>
        Sheet{' '}
        <input
          data-testid="sheet-id-input"
          value={id}
          onChange={(e) => {
            setId(e.target.value);
            load.reset();
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="sheet-load" disabled={load.isPending}>
        Load
      </button>{' '}
      Active sheet: <strong data-testid="sheet-current-id">{shown}</strong>
      {load.isError && <p data-testid="sheet-error">{load.error.message}</p>}
    </form>
  );
}
